  btn.disabled = true; btn.innerHTML = 'Submitting…';
  const r = await post('/deposit/manual/paste-sms', { depositId: _manDepId, text });
  if (btn) { btn.disabled = false; btn.innerHTML = 'Submit <span>&rarr;</span>'; }
